begin;
do $$
declare lesson jsonb; existing jsonb;
begin
  for lesson in select value from jsonb_array_elements($grammar_catalog_v2$[{"goalId":"infinitive-content-vs-purpose","grammarIds":["m-to-inf-noun","m-to-inf-adj-adv"],"version":2,"title":"같은 to play, 다른 일: 뭘? 왜?","objective":"to + 동사가 ‘무엇을 하고 싶은지·하려는지(내용)’를 말하는지, ‘왜 그 행동을 했는지(목적)’를 말하는지 문장을 보고 구분하고, 그 이유를 말할 수 있다.","rule":"to 뒤에 동사가 오면 먼저 to 앞부분을 읽고 질문을 만들어 보세요. ① ‘뭘 ~해?’라고 물을 때 to ...가 답이면, 그 동작은 앞 동사가 말하는 내용이에요(want 뒤처럼). ② ‘왜 ~했어?’라고 물을 때 to ...가 답이면, 그 행동을 한 목적이에요. 확인하는 방법은 to 앞에 in order를 넣어 보는 거예요. 목적이면 뜻이 그대로예요(I went outside in order to play). 내용이면 말이 이상해져요(I want in order to play ✗). 이렇게 보는 이유는, 영어가 to의 모양만으로는 역할을 알려 주지 않기 때문이에요. 앞 동사가 무엇을 필요로 하는지와 이야기 전체를 같이 봐야 해요.","boundary":"to ...를 뺐을 때 문장이 끝나는지는 참고만 하세요. The show began.은 그 자체로 완전한 문장이지만, The show began to change.의 to change는 ‘무엇이 시작됐어?’에 답해요. something to drink의 to drink는 ‘어떤 것?’에 답하는 또 다른 쓰임이에요. to school이나 look forward to playing에서는 to 뒤에 동사원형이 오지 않아요. 이번에는 행동의 내용과 목적을 구분해요.","examples":[{"sentence":"I want to play.","translation":"나는 놀고 싶어요.","chunks":[{"text":"I","role":"하는 사람(누가?)","term":"주어"},{"text":"want","role":"마음속으로 바란다는 말","term":"동사"},{"text":"to play","role":"‘뭘 원해?’에 답해요: 원하는 내용(놀기)","term":"to부정사구 · 목적어(명사처럼 쓰임)"}],"why":"‘뭘 원해?’라고 물으면 ‘놀기’라고 답해요. 그래서 to play는 want가 말하는 ‘원하는 것’ 자리를 채워요. play만 보면 동사(품사)지만, 이 문장에서 to play 전체는 ‘원하는 것’이라는 명사 같은 일(역할)을 해요. 품사와 문장 속 역할은 달라요."},{"sentence":"I went outside to play.","translation":"나는 놀려고 밖에 나갔어요.","chunks":[{"text":"I","role":"하는 사람(누가?)","term":"주어"},{"text":"went","role":"움직인 행동(갔어요)","term":"동사"},{"text":"outside","role":"어디로 갔는지(밖으로)","term":"부사"},{"text":"to play","role":"‘왜 나갔어?’에 답해요: 나간 이유(놀려고)","term":"to부정사구 · 부사처럼 쓰임(목적)"}],"why":"‘왜 밖에 나갔어?’라고 물으면 ‘놀려고’라고 답해요. 이 to play는 나간 이유(목적)를 말해요. 모양은 앞 문장의 to play와 똑같지만 하는 일이 달라요. I went outside.만으로도 ‘밖에 나갔어요’라는 말이 완성되어서, to play는 거기에 이유를 덧붙여요. in order를 넣어 I went outside in order to play.라고 해도 뜻이 같아요."}],"reasoning":{"id":"inf-reasoning-1","sentence":"She opened the window to get fresh air.","prompt":"to get fresh air는 이 문장에서 어떤 일을 할까요? 판단과 이유를 함께 고르세요.","options":[{"id":"content-needed","text":"‘뭘 열었어?’에 답하는 내용이에요. 이 부분이 없으면 ‘창문을 열었다’는 말이 끝나지 않아서 꼭 필요해요.","feedback":"‘뭘 열었어?’의 답은 이미 the window예요. to get fresh air는 ‘왜 열었어?’에 답해요. ‘신선한 공기를 쐬려고’ 창문을 연 거예요."},{"id":"purpose-question","text":"‘왜 열었어?’에 답하는 목적이에요. 창문을 연 이유(공기를 쐬려고)를 말해요.","feedback":"잘 골랐어요. ‘왜 열었어?’라고 물으니 ‘신선한 공기를 쐬려고’가 바로 답이 됐어요. in order를 넣어 She opened the window in order to get fresh air.라고 해도 뜻이 같다는 점도 목적이라는 확인이에요."},{"id":"always-to-rule","text":"목적이에요. 문장에 to가 들어 있으면 그 to ...는 항상 목적을 말하는 부분이에요.","feedback":"목적이라는 판단은 맞지만 이유가 틀렸어요. I want to play.에도 to가 있는데 그건 목적이 아니라 원하는 내용이에요. to의 모양이 아니라 ‘뭘?’인지 ‘왜?’인지 질문으로 판단해야 다른 문장에서도 맞아요."},{"id":"noun-modifier","text":"window를 설명해 줘요. ‘공기를 쐬는 창문’처럼 어떤 창문인지를 말하는 부분이에요.","feedback":"something to drink처럼 명사 뒤에서 그 명사를 설명하는 to ...도 있어요. 하지만 여기서는 ‘어떤 창문?’이 아니라 ‘왜 열었어?’에 답해요. 명사를 설명하는지 이유를 말하는지는 ‘어떤 것?’과 ‘왜?’ 중 어느 질문이 자연스러운지로 가려요."}],"correctOptionId":"purpose-question"},"repair":{"explanation":"다른 방법으로 다시 볼게요. 문장을 ‘핵심 문장’과 ‘to ...’로 나눠 보세요. 핵심 문장만 읽었을 때 ① 뜻이 비어서 ‘뭘?’이 궁금하면, to ...는 그 빈자리를 채우는 내용이에요. ② 이미 뜻이 완성돼서 ‘왜?’가 궁금하면, to ...는 이유(목적)예요. 예를 들어 Mina likes ___.만 읽으면 ‘뭘 좋아해?’가 궁금해요. 그 자리를 to draw가 채워요. 반대로 Mina went home.만 읽으면 뜻이 완성돼서 ‘왜 갔어?’가 궁금해요. 거기에 to draw를 붙이면 집에 간 이유가 돼요. ‘빈칸을 채우는 말인가, 이유를 붙이는 말인가’를 보세요.","example":{"sentence":"Mina likes to draw.","translation":"미나는 그리기를 좋아해요.","chunks":[{"text":"Mina","role":"하는 사람(누가?)","term":"주어"},{"text":"likes","role":"좋아한다는 마음을 말하는 말","term":"동사"},{"text":"to draw","role":"‘뭘 좋아해?’에 답해요: 좋아하는 내용(그리기)","term":"to부정사구 · 목적어(명사처럼 쓰임)"}],"why":"핵심 문장만 읽으면 Mina likes ___.가 되어 ‘뭘 좋아해?’가 궁금해져요. to draw가 그 빈자리를 채워요. 그래서 이 to ...는 이유가 아니라 좋아하는 내용이에요."},"practice":{"id":"inf-repair-1","sentence":"Sam hopes to be a doctor.","prompt":"to be a doctor는 이 문장에서 어떤 일을 할까요? 판단과 이유를 함께 고르세요.","options":[{"id":"purpose-why","text":"‘왜 바라?’에 답하는 목적이에요. 의사가 되려고 바라는 것이니까 이유를 말해요.","feedback":"‘의사가 되려고 바란다’고 읽으면 말이 어색해요. 바라는 것이 바로 ‘의사가 되는 것’이에요. Sam hopes ___.에서 ‘뭘 바라?’가 궁금하고, to be a doctor가 그 답이에요. 그래서 목적이 아니라 내용이에요."},{"id":"to-means-purpose","text":"목적이에요. to는 늘 ‘~하려고’라는 뜻이라서 이 문장에서도 그렇게 읽어요.","feedback":"to가 늘 ‘~하려고’는 아니에요. I want to play.도 ‘놀려고 원해요’가 아니라 ‘놀고 싶어요’예요. 뜻은 문장에 맞게 ‘뭘?’인지 ‘왜?’인지 보고 정해요."},{"id":"content-blank","text":"‘뭘 바라?’에 답하는 내용이에요. 바라는 것이 to be a doctor예요.","feedback":"잘 골랐어요. 핵심 문장만 읽고 ‘뭘 바라?’가 궁금한지 확인한 것이 좋은 단서였어요. to be a doctor는 바라는 내용을 채우는 말이에요."},{"id":"noun-modifier","text":"doctor를 설명해요. ‘어떤 의사’인지를 말해 주는 부분이에요.","feedback":"doctor는 이미 ‘의사’라는 말이에요. 설명이 필요한 곳이 아니에요. 문장이 비어 있는 곳은 hopes 뒤예요. ‘뭘 바라?’에 답하는 내용이에요."}],"correctOptionId":"content-blank"}},"transfer":{"id":"inf-transfer-1","sentence":"Tom saved money to buy a new bike.","prompt":"to buy a new bike는 이 문장에서 어떤 일을 할까요? 판단과 이유를 함께 고르세요.","options":[{"id":"content-what-saved","text":"‘뭘 모았어?’에 답하는 내용이에요. Tom이 모은 것이 a new bike라서 꼭 필요한 부분이에요.","feedback":"‘뭘 모았어?’의 답은 이미 money예요. 자전거는 모은 것이 아니라 사려고 하는 물건이에요. to buy a new bike는 돈을 모은 이유를 말해요."},{"id":"always-save-purpose","text":"목적이에요. to buy가 나오면 언제나 ‘사기 위해서’라는 뜻이에요.","feedback":"이 문장에서는 목적이 맞아요. Tom plans to buy a new bike.에서도 to buy가 나오지만, 여기서는 ‘뭘 계획해?’에 답해요. 두 문장에서 to buy가 각각 어떤 질문에 답하는지 비교해 보세요."},{"id":"noun-modifier","text":"bike를 설명해요. ‘살 자전거’처럼 어떤 자전거인지를 말하는 부분이에요.","feedback":"to buy가 bike 앞에서 bike를 설명하는 말은 아니에요. a new bike는 buy의 목적어이고, to buy a new bike 전체가 ‘왜 돈을 모았어?’에 답해요."},{"id":"purpose-why-saved","text":"‘왜 돈을 모았어?’에 답하는 목적이에요. Tom saved money.만으로도 뜻이 완성돼요.","feedback":"잘 골랐어요. Tom saved money.만 읽어도 뜻이 완성되고, ‘왜?’가 궁금해지죠. ‘새 자전거를 사려고’가 그 답이에요. 질문으로 판단한 것이 좋은 근거예요."}],"correctOptionId":"purpose-why-saved"},"delayed":{"id":"inf-delayed-1","sentence":"Ella promised to call me tonight.","prompt":"to call me tonight는 이 문장에서 어떤 일을 할까요? 판단과 이유를 함께 고르세요.","options":[{"id":"content-promised","text":"‘뭘 약속했어?’에 답하는 내용이에요. 약속한 것이 to call me tonight예요.","feedback":"잘 골랐어요. 약속한 것이 ‘전화하는 것’ 자체예요. ‘뭘 약속했어?’라는 질문으로 빈자리를 확인한 것이 좋은 근거였어요."},{"id":"purpose-why-promised","text":"‘왜 약속했어?’에 답하는 목적이에요. 전화하려고 약속했다는 뜻으로 읽어요.","feedback":"‘전화하려고 약속했다’로 읽으면 이상해요. 약속한 것이 바로 ‘오늘 밤에 전화하는 것’이에요. ‘왜?’가 아니라 ‘뭘 약속했어?’에 답하니 내용이에요."},{"id":"always-promise-purpose","text":"목적이에요. 동사 뒤에 to가 나오면 그 to ...는 대부분 목적을 말해요.","feedback":"동사 뒤에 to가 나온다고 목적은 아니에요. I want to play.처럼 원하는 내용일 때도 많아요. ‘뭘?’인지 ‘왜?’인지 질문으로 판단하세요."},{"id":"modifier-time","text":"tonight를 설명해요. ‘오늘 밤에 해야 할’처럼 때를 꾸며 주는 부분이에요.","feedback":"tonight는 to call me tonight 안에서 ‘언제 전화하는지’를 말하는 시간 표현이에요. to call me tonight 전체가 문장에서 어떤 일을 하는지는 ‘뭘 약속했어?’로 판단해요."}],"correctOptionId":"content-promised"}},{"goalId":"past-question-base-verb","grammarIds":["m-past"],"version":2,"title":"과거를 알리는 자리: went인가, Did인가","objective":"과거 일반동사 문장에서 과거 신호가 어디에 붙는지 판단하고, Did 질문의 뒤 동사를 원형으로 쓰는 이유를 말할 수 있다.","rule":"You went home.에서는 went가 ‘가다’와 ‘지난 일’을 함께 알려 줘요. 같은 일을 Did you go home?으로 물으면, Did가 ‘지난 일’을 알려 주고 go는 ‘가다’라는 동작만 말해요. 영어에서는 이렇게 Did로 묻는 부분의 동작을 원형으로 써요. 그래서 Did you went home?을 Did you go home?으로 고쳐요.","boundary":"범위와 조건: (1) 이 규칙은 일반동사 과거문이에요. be동사는 Did를 쓰지 않고 Were you at home?처럼 Were/Was를 앞으로 보내요. (2) 질문의 주어가 의문사이면 Did 없이 과거형을 써요: Who went home? (3) 불규칙 동사(go–went)만 그런 게 아니에요. 규칙 동사도 같아요. 평서문은 played, Did 질문은 play예요. (4) 일상 대화에서는 You went home?처럼 말투만 올려 묻기도 하지만, 이 수업은 Did로 질문을 만드는 방법을 다뤄요. 부정문도 같은 원리라서 didn’t 뒤에는 원형이 와요(You didn’t go home).","examples":[{"sentence":"You went home.","translation":"너는 집에 갔어.","chunks":[{"text":"You","role":"하는 사람(누가?)","term":"주어"},{"text":"went","role":"‘가다’와 ‘과거’ 신호가 한 단어에 합쳐진 모양","term":"동사 과거형"},{"text":"home","role":"어디로 갔는지(집으로)","term":"부사"}],"why":"went는 ‘가다(go)’에 ‘과거’ 신호가 합쳐진 모양이에요. 과거 신호가 동사 안에 들어 있어요. 문장 앞에 Did가 없을 때는 이렇게 동사 모양이 과거를 알려 줘요."},{"sentence":"Did you go home?","translation":"너는 집에 갔니?","chunks":[{"text":"Did","role":"질문을 만들고 과거를 알려 주는 도우미","term":"조동사"},{"text":"you","role":"하는 사람(누가?)","term":"주어"},{"text":"go","role":"동작 이름만 남은 모양(가다)","term":"동사원형"},{"text":"home","role":"어디로 갔는지(집으로)","term":"부사"}],"why":"과거 신호가 Did로 옮겨 갔어요. 그래서 뒤 동사 go는 동작 이름만 남은 원형이에요. went를 쓰면 과거 신호가 Did와 went에서 두 번 나와요."},{"sentence":"You played soccer.","translation":"너는 축구를 했어.","chunks":[{"text":"You","role":"하는 사람(누가?)","term":"주어"},{"text":"played","role":"‘놀다/하다’에 ‘과거’ 신호(-ed)가 붙은 모양","term":"동사 과거형"},{"text":"soccer","role":"무슨 운동을 했는지","term":"명사"}],"why":"규칙 동사도 같아요. played는 play에 과거 신호 -ed가 붙은 모양이에요. went처럼 모양이 크게 바뀌지 않아도 과거 신호가 동사 안에 있어요."},{"sentence":"Did you play soccer?","translation":"너는 축구를 했니?","chunks":[{"text":"Did","role":"질문을 만들고 과거를 알려 주는 도우미","term":"조동사"},{"text":"you","role":"하는 사람(누가?)","term":"주어"},{"text":"play","role":"동작 이름만 남은 모양(하다)","term":"동사원형"},{"text":"soccer","role":"무슨 운동을 했는지","term":"명사"}],"why":"질문이 되면 -ed가 사라지고 play만 남아요. 과거 신호를 Did가 맡았기 때문이에요. 불규칙 동사(go)뿐 아니라 규칙 동사(play)도 같은 원리예요."}],"reasoning":{"id":"past-reasoning-1","sentence":"Did Min-ho ___ his umbrella at school?","prompt":"빈칸에 알맞은 모양과 이유를 함께 고르세요. (forget = 잊어버리다)","options":[{"id":"forgot-time","text":"forgot — 지난 일을 묻는 문장이라서 동사도 과거형으로 바꿔서 써요.","feedback":"지난 일이라는 판단은 맞아요. 하지만 그 신호는 이미 Did가 맡고 있어요. forgot을 쓰면 Did forgot처럼 과거가 두 번 나와요. 동사 모양으로 과거를 알리는 것은 Did가 없는 평서문일 때예요(Min-ho forgot his umbrella.)."},{"id":"forget-did","text":"forget — Did가 과거를 알려 줘서 동사는 원형이에요.","feedback":"잘 골랐어요. Did가 지난 일을 알려 주므로 동작은 원형 forget으로 써요. Min-ho forgot his umbrella.처럼 같은 일을 설명하는 문장에서는 forgot이 지난 일을 알려 줘요."},{"id":"forgets-s","text":"forgets — Min-ho는 한 명이라서 동사에 s를 붙여서 써요.","feedback":"-s는 현재 이야기에서 한 명인 주어(he, she, Min-ho) 뒤에 붙는 모양이에요(Min-ho forgets his umbrella.). 여기서는 Did가 있어요. Did가 있으면 동사에 -s도 -ed도 붙이지 않고 원형을 써요."},{"id":"forget-always-question","text":"forget — 질문 문장에서는 동사를 언제나 원형으로 써요.","feedback":"모양은 맞지만 이유가 틀렸어요. 질문이라고 늘 원형은 아니에요. Who forgot his umbrella?처럼 Did 없이 과거형을 쓰는 질문도 있고, Was he late?처럼 be동사 질문도 있어요. 원형을 쓰는 진짜 이유는 Did가 과거 신호를 맡았기 때문이에요."}],"correctOptionId":"forget-did"},"repair":{"explanation":"다른 방법으로 볼게요. 과거 문장은 두 가지를 알려 줘요. ‘무슨 동작?’과 ‘언제(과거)?’예요. 평서문에서는 두 가지가 동사 한 단어에 같이 들어 있어요: watched = watch(동작) + -ed(과거). 질문에서는 둘이 나뉘어요. 과거는 앞의 Did가, 동작 이름은 뒤의 watch가 맡아요. 과거 신호 칸이 하나뿐이라서, 동사에 -ed를 또 넣을 자리가 없어요. 아래 문장을 칸으로 나눠 보세요.","example":{"sentence":"Did she watch TV?","translation":"그녀는 TV를 봤니?","chunks":[{"text":"Did","role":"과거 신호 칸 + 질문을 만드는 말","term":"조동사"},{"text":"she","role":"하는 사람(누가?)","term":"주어"},{"text":"watch","role":"동작 이름 칸(보다)","term":"동사원형"},{"text":"TV","role":"무엇을 봤는지","term":"명사"}],"why":"평서문 She watched TV.에서는 watched 한 단어가 ‘보다 + 과거’를 같이 맡았어요. 질문으로 바꾸면 과거는 Did로 가고, watch에는 동작 이름만 남아요. 과거 신호 칸이 하나뿐이라서 watched를 쓰면 안 돼요."},"practice":{"id":"past-repair-1","sentence":"Did your sister ___ a cake yesterday?","prompt":"빈칸에 알맞은 모양과 이유를 함께 고르세요. (bake = 굽다)","options":[{"id":"baked-yesterday","text":"baked — yesterday가 있으니까 동사에도 -ed를 붙여서 써요.","feedback":"yesterday는 지난 일이라는 시간 단서일 뿐이에요. 동사 모양을 정하는 것은 Did예요. Did가 이미 과거 신호를 맡았으니 baked가 아니라 bake예요. Yesterday, your sister baked a cake.처럼 Did 없는 평서문일 때 baked를 써요."},{"id":"bakes-s","text":"bakes — your sister는 한 명이라서 동사에 s가 필요해요.","feedback":"-s는 현재의 한 명 주어 뒤에서 쓰는 모양이에요. 여기서는 Did가 있어서 -s도 -ed도 붙이지 않아요. 칸마다 신호는 하나씩이에요: 과거 신호는 Did, 동작 이름은 bake."},{"id":"bake-did-slot","text":"bake — Did가 과거 칸을 맡아서 동사는 동작 이름만 써요.","feedback":"잘 골랐어요. 과거 신호 칸은 Did가 가지고 있고, 동사 칸에는 동작 이름 bake만 남아요. 칸으로 나눠 본 방법이 맞게 쓰였어요."},{"id":"bake-yesterday-reason","text":"bake — yesterday가 있으면 동사는 원형을 쓰는 거예요.","feedback":"모양은 맞지만 이유가 틀렸어요. yesterday는 동사 모양을 정하지 않아요. Yesterday, she baked a cake.처럼 평서문에서는 baked를 써요. 원형인 이유는 Did가 과거 신호를 맡았기 때문이에요."}],"correctOptionId":"bake-did-slot"}},"transfer":{"id":"past-transfer-1","sentence":"Did Lucy found her phone?","prompt":"이 문장이 맞는지 판단하고 이유를 함께 고르세요. (find = 찾다, found = find의 과거형)","options":[{"id":"right-irregular-same","text":"맞아요. found는 불규칙 동사라서 질문에서도 모양이 바뀌지 않고 그대로예요.","feedback":"불규칙 동사도 Did 질문에서는 원형이 돼요. Lucy found her phone.의 found는 find에 과거 신호가 합쳐진 모양이라서, 과거 신호를 Did가 맡으면 find만 남아요. 올바른 문장은 Did Lucy find her phone?이에요."},{"id":"wrong-does","text":"틀려요. Lucy는 한 명이라서 Did 대신 Does를 써야 하기 때문이에요.","feedback":"틀리다는 판단은 맞지만 이유가 틀렸어요. Does는 현재 질문에서 쓰고, 과거 질문은 주어가 한 명이든 여럿이든 Did를 써요. 고칠 곳은 found예요. Did 뒤에는 find를 써요."},{"id":"right-past-needs-past","text":"맞아요. 지난 일을 묻는 문장이라서 질문에서도 found처럼 과거형을 써요.","feedback":"지난 일이라는 점은 맞아요. 하지만 과거 신호는 이미 Did가 맡고 있어요. found까지 쓰면 과거 신호가 두 번이 돼요. Did가 있으면 동사는 find예요."},{"id":"wrong-double-signal","text":"틀려요. Did가 과거를 알려 줘서 found가 아니라 find여야 해요.","feedback":"잘 골랐어요. Did가 지난 일을 알려 주고 동작은 원형 find가 말해요. Did Lucy find her phone?으로 고쳐요."}],"correctOptionId":"wrong-double-signal"},"delayed":{"id":"past-delayed-1","sentence":"Where did they ___ lunch after school?","prompt":"빈칸에 알맞은 모양과 이유를 함께 고르세요. (eat = 먹다)","options":[{"id":"eat-did-reason","text":"eat — did가 과거를 알려 줘서 동사는 원형이에요.","feedback":"잘 골랐어요. Where가 앞에 있어도 did가 과거 신호를 맡고 있어서 동사는 eat이에요. 의문사 질문에서도 같은 기준이 쓰였어요."},{"id":"ate-past-story","text":"ate — 지난 일이니까 동사도 과거형으로 바꿔서 써요.","feedback":"지난 일이라는 판단은 맞아요. 하지만 그 신호는 did가 맡고 있어요. ate를 쓰면 did와 ate에서 과거 신호가 두 번 나와요. 과거형 ate는 They ate lunch after school.처럼 did 없는 평서문에서 써요."},{"id":"eating-where","text":"eating — Where로 묻는 질문에서는 동사에 -ing 모양을 써요.","feedback":"Where로 묻는 질문이라도 동사 모양이 -ing로 바뀌지는 않아요. -ing는 ‘하는 중’을 말하는 be동사 문장(Where are they eating?)에서 써요. did 뒤에는 원형 eat이에요."},{"id":"eat-where-always","text":"eat — Where가 있으면 동사는 언제나 원형을 쓰는 거예요.","feedback":"eat은 맞아요. Where were they yesterday?에도 Where가 있지만 원형 be를 쓰지 않아요. 이 문제에서 eat을 쓰는 이유는 Where 때문이 아니라 did가 과거를 알려 주기 때문이에요."}],"correctOptionId":"eat-did-reason"}},{"goalId":"hypothetical-were-vs-past","grammarIds":["m-subjunctive","past-be"],"version":2,"title":"was일까, were일까: 실제 일인가, 상상인가","objective":"문장이 ‘실제로 있었던 일’인지 ‘지금 사실과 다른 상상’인지 먼저 판단하고, 그에 맞게 was와 were를 고를 수 있다.","rule":"이 문장은 지난 상태를 이야기하나요, 지금과 다른 상황을 상상하나요? I was tired yesterday.는 어제의 상태를 말해서 I 뒤에 was를 써요. If I were tired now, I would go to bed.는 지금 피곤하다고 가정하고 그랬을 때의 결과를 말해요. 이 수업에서는 이런 가정에 I, he, she, it 뒤에도 were를 써요. 예문 속 would나 could는 가정이 맞을 때 어떤 일이 일어날지 알려 줘요.","boundary":"범위와 조건: (1) were가 보인다고 늘 상상은 아니에요. we, you, they는 실제 지난 일에도 were를 써요(They were at the park). 상상인지 알려 주는 단서는 If, 지금 사실과의 차이, 그리고 would/could예요. (2) If가 있다고 늘 상상도 아니에요. 정말 있었을 수 있는 지난 일을 조건으로 말할 때는 was를 써요(If I was rude to you, I’m sorry). 이때는 ‘정말 그랬을 수도 있다’는 뜻이라서 상상이 아니에요. (3) 일상 대화에서는 상상 문장에도 If I was …라고 말하는 사람이 많아요. 이 수업과 학교 문법, 시험에서는 were를 기준으로 삼아요. (4) I wish I were … 도 같은 원리예요.","examples":[{"sentence":"I was tired yesterday.","translation":"나는 어제 피곤했어요.","chunks":[{"text":"I","role":"하는 사람(누가?)","term":"주어"},{"text":"was","role":"실제로 있었던 지난 상태를 말하는 be동사","term":"be동사 과거형"},{"text":"tired","role":"어떤 상태였는지(피곤한)","term":"형용사"},{"text":"yesterday","role":"언제인지(어제)","term":"부사"}],"why":"어제 실제로 피곤했던 지난 일이에요. 일어난 사실을 말하니까 I 뒤에 was를 써요. yesterday가 이 일이 지난 일이라는 단서예요. 상상이 아니라 사실이에요."},{"sentence":"If I were tired now, I would go to bed.","translation":"내가 지금 피곤하다면, 나는 자러 갈 텐데.","chunks":[{"text":"If","role":"‘만약 ~라면’ 하고 상상을 시작하는 말","term":"접속사"},{"text":"I","role":"하는 사람(누가?)","term":"주어"},{"text":"were","role":"지금 사실과 다르다는 표시(상상 표시)","term":"be동사 · 가정법 과거"},{"text":"tired","role":"어떤 상태라고 상상하는지(피곤한)","term":"형용사"},{"text":"now","role":"언제인지(지금)","term":"부사"},{"text":"I","role":"하는 사람(누가?)","term":"주어"},{"text":"would go","role":"그렇다면 했을 행동(갈 텐데)","term":"조동사 + 동사"},{"text":"to bed","role":"어디로 가는지(잠자리로)","term":"전치사구"}],"why":"지금 나는 피곤하지 않아요. 피곤하다고 상상해서 말하는 문장이에요. 지금 사실과 다른 상상이라서 I 뒤에도 were를 써요. would go가 ‘그렇다면 갈 텐데’라는 상상의 결과를 보여 줘요. 두 문장 모두 I와 tired가 나오지만, 실제 일이면 was, 지금과 다른 상상이면 were예요."},{"sentence":"He was late for school this morning.","translation":"그는 오늘 아침 학교에 늦었어요.","chunks":[{"text":"He","role":"하는 사람(누가?)","term":"주어"},{"text":"was","role":"실제로 있었던 지난 상태를 말하는 be동사","term":"be동사 과거형"},{"text":"late","role":"어떤 상태였는지(늦은)","term":"형용사"},{"text":"for school","role":"무엇에 늦었는지(학교에)","term":"전치사구"},{"text":"this morning","role":"언제인지(오늘 아침)","term":"시간을 말하는 말"}],"why":"말하는 사람이 오늘 아침에 학교에 늦은 일을 지난 사실로 말하고 있어요. 그래서 he 뒤에 was를 써요."},{"sentence":"If she were taller, she could play basketball.","translation":"그녀가 더 키가 크다면, 농구를 할 수 있을 텐데.","chunks":[{"text":"If","role":"‘만약 ~라면’ 하고 상상을 시작하는 말","term":"접속사"},{"text":"she","role":"하는 사람(누가?)","term":"주어"},{"text":"were","role":"지금 사실과 다르다는 표시(상상 표시)","term":"be동사 · 가정법 과거"},{"text":"taller","role":"더 키가 큰 상태","term":"형용사 비교급"},{"text":"she","role":"하는 사람(누가?)","term":"주어"},{"text":"could play","role":"그렇다면 할 수 있을 행동","term":"조동사 + 동사"},{"text":"basketball","role":"무슨 운동인지","term":"명사"}],"why":"지금은 그녀가 그렇게 키가 크지 않아요. 더 크다고 상상하는 문장이에요. she는 한 명이지만 상상 문장이라서 were를 써요. 결과 부분에 could가 있어 ‘그렇다면 할 수 있을 텐데’라는 상상이에요."}],"reasoning":{"id":"were-reasoning-1","sentence":"If Jisu ___ here now, she would help us.","prompt":"먼저 이 문장이 어떤 상황인지 판단하고, 빈칸에 알맞은 말을 고르세요.","options":[{"id":"was-single","text":"was — Jisu는 한 명(she)이라서 동사에 was를 써야 해요.","feedback":"한 명이라서 was를 쓰는 것은 실제 지난 일을 말할 때예요. 이 문장에는 now와 would가 있어요. 지금 지수가 여기에 없다는 사실이 숨어 있는 상상 문장이라서, Jisu(she)에도 were를 써요."},{"id":"was-real-past","text":"was — 지수가 여기에 실제로 있었던 지난 일을 말하는 문장이에요.","feedback":"yesterday처럼 지난 일을 알려 주는 말이 없어요. 오히려 now와 would가 있어요. ‘지금 여기에 있다면 도와줄 텐데’라는 뜻이라서 실제 지난 일이 아니라 상상이에요. 그래서 were예요."},{"id":"were-imagine-now","text":"were — 지금 지수가 없는데, 있다고 상상하는 말이에요.","feedback":"잘 골랐어요. now와 would를 보고 ‘지금 사실과 다른 상상’이라고 먼저 판단했어요. 상상 문장이라서 she에 해당하는 Jisu 뒤에도 were를 써요."},{"id":"were-if-always","text":"were — If가 있는 문장에서는 항상 were를 쓰는 거예요.","feedback":"모양은 맞지만 이유가 틀렸어요. If가 있어도 정말 있었을 수 있는 지난 일을 조건으로 말할 때는 was를 써요(If I was rude, I’m sorry). 먼저 ‘지금 사실과 다른 상상인가?’를 보세요. 여기서는 now와 would가 그 단서예요."}],"correctOptionId":"were-imagine-now"},"repair":{"explanation":"실제 상황과 상상하는 상황을 한 줄씩 나눠 봐요. 실제 상황: 오늘은 맑지 않아요. 상상하는 상황: 오늘 맑다면 공원에 갈 텐데요. 아래 문장은 두 번째 상황을 말해서 it 뒤에 were를 써요. 어제 실제로 맑았다고 말할 때는 It was sunny yesterday.처럼 was를 써요.","example":{"sentence":"If it were sunny today, we would go to the park.","translation":"오늘 날씨가 맑다면, 우리는 공원에 갈 텐데.","chunks":[{"text":"If","role":"‘만약 ~라면’ 하고 상상을 시작하는 말","term":"접속사"},{"text":"it","role":"날씨를 말할 때 쓰는 말","term":"주어"},{"text":"were","role":"지금 사실과 다르다는 표시(상상 표시)","term":"be동사 · 가정법 과거"},{"text":"sunny","role":"어떤 날씨인지(맑은)","term":"형용사"},{"text":"today","role":"언제인지(오늘)","term":"부사"},{"text":"we","role":"하는 사람(누가?)","term":"주어"},{"text":"would go","role":"그렇다면 했을 행동(갈 텐데)","term":"조동사 + 동사"},{"text":"to the park","role":"어디로 가는지(공원으로)","term":"전치사구"}],"why":"오늘은 맑지 않다는 사실이 문장 속에 숨어 있어요. 맑다고 상상하니까 it 뒤에도 were를 써요. 결과는 would go로 ‘그랬다면 갔을 텐데’라는 상상이에요."},"practice":{"id":"were-repair-1","sentence":"If my brother ___ older, he could drive a car.","prompt":"먼저 이 문장이 어떤 상황인지 판단하고, 빈칸에 알맞은 말을 고르세요.","options":[{"id":"was-one-person","text":"was — my brother는 한 명이라서 동사에 was를 써야 해요.","feedback":"한 명인 것은 맞아요. 하지만 was는 실제 지난 일에 쓰고, 여기는 상상이에요. 지금 남동생이 아직 운전할 수 없다는 사실이 숨어 있고, could drive가 ‘그렇다면 할 수 있을 텐데’를 보여 줘요. 그래서 were예요."},{"id":"were-plural-he","text":"were — he가 복수여서 동사에 were를 써야 해요.","feedback":"모양은 맞지만 이유가 틀렸어요. he는 한 명이에요. 한 명인 he 뒤에 were를 쓰는 이유는 복수라서가 아니라 ‘지금 사실과 다른 상상’이라서예요."},{"id":"was-past-story","text":"was — 이미 지나간 일을 말하는 문장이라서 was를 써요.","feedback":"지난 일을 알려 주는 말(yesterday 등)이 없어요. 지금 운전할 수 없는 사실과 다르게, 더 나이가 많다고 상상하는 문장이에요. 그래서 was가 아니라 were예요."},{"id":"were-imagine-brother","text":"were — 지금은 운전을 못 하는데, 더 나이가 많다고 상상해요.","feedback":"잘 골랐어요. 현실 확인 3단계처럼 ‘지금 사실은 달라요’라는 점을 먼저 찾았어요. could drive가 상상의 결과예요. 상상 문장이라서 한 명인 my brother(he) 뒤에도 were를 써요."}],"correctOptionId":"were-imagine-brother"}},"transfer":{"id":"were-transfer-1","sentence":"Yesterday, my brother were at the library.","prompt":"이 문장이 맞는지 판단하고 이유를 함께 고르세요.","options":[{"id":"right-all-were","text":"맞아요. 상상이 아니라도 be동사 과거형은 모두 were를 쓰는 거예요.","feedback":"be동사 과거형이 모두 were는 아니에요. I, he, she, it(my brother는 he)은 실제 지난 일에 was를 써요. we, you, they는 were예요. were가 I, he, she, it에 쓰이는 때는 ‘지금 사실과 다른 상상’일 때뿐이에요."},{"id":"wrong-no-if","text":"틀려요. If가 없으면 were는 어떤 문장에서도 쓸 수 없어요.","feedback":"틀리다는 판단은 맞지만 이유가 틀렸어요. If가 없어도 They were at the park.처럼 were를 써요. 이 문장이 틀린 이유는, 어제 실제로 있었던 일인데 한 명인 my brother(he) 뒤에 were를 썼기 때문이에요."},{"id":"wrong-real-past-was","text":"틀려요. 어제 실제 일이라서 my brother(he)에는 was를 써요.","feedback":"잘 골랐어요. Yesterday가 실제 지난 일이라는 단서이고, If나 would 같은 상상 단서는 없어요. 그래서 was를 써서 Yesterday, my brother was at the library.로 고쳐요."},{"id":"right-imagine","text":"맞아요. 도서관에 가 있는 일을 상상해서 말하는 문장이에요.","feedback":"이 문장은 어제 도서관에 있었던 일을 지난 사실로 말하려는 문장이에요. my brother는 he에 해당하므로 이 문장에서는 was를 써요."}],"correctOptionId":"wrong-real-past-was"},"delayed":{"id":"were-delayed-1","sentence":"If Dad ___ free today, he would take us fishing.","prompt":"먼저 이 문장이 어떤 상황인지 판단하고, 빈칸에 알맞은 말을 고르세요. (free = 한가한, 시간이 있는)","options":[{"id":"was-one-dad","text":"was — Dad는 한 명이라서 동사에 was를 써야 해요.","feedback":"한 명이라서 was를 쓰는 것은 실제 지난 일일 때예요. 이 문장은 today와 would가 있고, 오늘 아빠가 한가하지 않다는 사실이 숨어 있는 상상이에요. 그래서 한 명인 Dad 뒤에도 were예요."},{"id":"were-imagine-dad","text":"were — 오늘 아빠가 한가하지 않은데, 한가하다고 상상해요.","feedback":"잘 골랐어요. today와 would를 보고 ‘지금 사실과 다른 상상’이라고 먼저 판단했어요. 상상 문장이라서 한 명인 Dad 뒤에도 were를 써요."},{"id":"was-real-free","text":"was — 아빠가 실제로 한가했던 지난 일을 말하는 문장이에요.","feedback":"지난 일을 알려 주는 말이 없고, today와 would가 있어요. ‘오늘 시간이 있다면 낚시를 데려갈 텐데’라는 상상이에요. 실제로 한가했던 일을 말하는 문장이 아니라서 was가 아니라 were예요."},{"id":"were-if-all","text":"were — If 뒤에는 모든 문장에서 were를 쓰는 거예요.","feedback":"모양은 맞지만 이유가 틀렸어요. If 뒤에도 정말 있었을 수 있는 지난 일을 말할 때는 was를 써요(If Dad was late, I’m sorry). 여기서 were인 이유는 지금 사실과 다른 상상이기 때문이에요."}],"correctOptionId":"were-imagine-dad"}}]$grammar_catalog_v2$::jsonb) loop
    insert into public.grammar_content_versions(goal_id,version,content)
      values(lesson->>'goalId',(lesson->>'version')::integer,lesson) on conflict do nothing;
    select content into strict existing from public.grammar_content_versions
      where goal_id=lesson->>'goalId' and version=(lesson->>'version')::integer;
    if existing is distinct from lesson then
      raise exception 'grammar_version_conflict: %/%',lesson->>'goalId',lesson->>'version';
    end if;
  end loop;
end $$;
commit;
